import '../models/masonry_input.dart'; import '../models/productivity_standard.dart'; import 'estimate_cost_calculator.dart'; import 'labour_calculator.dart'; import 'masonry_calculator.dart'; import 'opening_calculator.dart'; import 'productivity_calculator.dart';
class MasonryV2Calculator { static MasonryEstimateResult calculate(MasonryInput input) { if(input.thicknessMm<=0) throw ArgumentError('Enter a valid wall thickness.'); if(input.wastagePercent<0) throw ArgumentError('Wastage cannot be negative.'); final area=OpeningCalculator.calculate(grossArea:input.grossArea,openings:input.openings); final takeoff=MasonryCalculator.calculate(length:area.netArea,height:1,walls:1,thicknessMm:input.thicknessMm,unitSize:input.unitSize,cementPart:input.cementPart,sandPart:input.sandPart,wastagePercent:input.wastagePercent); final productivity=ProductivityCalculator.calculate(quantity:takeoff.masonryVolume,standard:ProductivityStandard(name:'Reference masonry productivity',basis:'m³',baseQuantity:1,daysPerBaseQuantity:{LabourRole.mason:input.masonDaysPerM3,LabourRole.helper:input.helperDaysPerM3},maximumCrewPerRole:3),crew:{LabourRole.mason:input.masons,LabourRole.helper:input.helpers}); final labour=LabourCalculator.calculate(productivity:productivity,dailyWages:{LabourRole.mason:input.masonDailyWage,LabourRole.helper:input.helperDailyWage}); final material=EstimateCostCalculator.total([takeoff.unitCount*input.unitRate,takeoff.cementBags*input.cementRatePerBag,takeoff.sandM3*input.sandRatePerM3]); return MasonryEstimateResult(takeoff:takeoff,input:input,area:area,productivity:productivity,labour:labour,materialCost:material,totalCost:material+labour.totalCost,costPerSquareMetre:(material+labour.totalCost)/area.netArea); } }

